raw_model_outputs:
# 0: walk to bathroom
	walk('bathroom')
	# 1: find toothbrush
	find('toothbrush')
	# 2: grab toothbrush
	assert('close' to 'toothbrush')
		else: find('toothbrush')
	grab('toothbrush')
	# 3: find toothpaste
	find('toothpaste')
	# 4: open toothpaste
	assert('close' to 'toothpaste')
		else: find('toothpaste')
	assert('toothpaste' is 'closed')
		else: close('toothpaste')
	open('toothpaste')
	# 5: put toothpaste on toothbrush
	assert('toothbrush' in 'hands')
		else: find('toothbrush')
		else: grab('toothbrush')
	assert('close' to 'toothpaste')
		else: find('toothpaste')
	assert('toothpaste' is 'opened')
		else: open('toothpaste')
	putin('toothpaste', 'toothbrush')
	# 6: close toothpaste
	assert('close' to 'toothpaste')
		else: find('toothpaste')
	assert('toothpaste' is 'opened')
		else: open('toothpaste')
	close('toothpaste')
	# 7: put toothpaste back
	assert('toothpaste' in 'hands')
		else: find('toothpaste')
		else: grab('toothpaste')
	find('bathroomcounter')
	assert('close' to 'bathroomcounter')
		else: find('bathroomcounter')
	putback('toothpaste', 'bathroomcounter')
	# 8: find faucet
	find('faucet')
	# 9: turn on faucet
	assert('close' to 'faucet')
		else: find('faucet')
	assert('faucet' is 'switchoff')
		else: switchoff('faucet')
	switchon('faucet')
	# 10: wet toothbrush
	assert('toothbrush' in 'hands')
		else: find('toothbrush')
		else: grab('toothbrush')
	assert('close' to 'faucet')
		else: find('faucet')
	assert('faucet' is 'switchon')
		else: switchon('faucet')
	putin('toothbrush', 'sink')
	# 11: brush teeth
	# (scrubbing action implied by holding wet, pasted toothbrush at mouth)
	assert('toothbrush' in '

